DROP POLICY IF EXISTS el_auth_read ON public.estoque_lotes;
CREATE POLICY el_auth_read ON public.estoque_lotes
  FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS el_auth_write ON public.estoque_lotes;
CREATE POLICY el_auth_write ON public.estoque_lotes
  FOR ALL TO authenticated USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS el_service_all ON public.estoque_lotes;
CREATE POLICY el_service_all ON public.estoque_lotes
  FOR ALL TO service_role USING (true) WITH CHECK (true);

