ALTER TABLE public.perdas_produtos ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS pp_auth_read ON public.perdas_produtos;
CREATE POLICY pp_auth_read ON public.perdas_produtos
  FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS pp_service_all ON public.perdas_produtos;
CREATE POLICY pp_service_all ON public.perdas_produtos
  FOR ALL TO service_role USING (true) WITH CHECK (true);

-- 4. noaa_customer_memory (PII LGPD, escrita só via noaa-chat/whatsapp)
