DROP POLICY IF EXISTS ncm_service_all ON public.noaa_customer_memory;
CREATE POLICY ncm_service_all ON public.noaa_customer_memory
  FOR ALL TO service_role USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS ncm_auth_read ON public.noaa_customer_memory;
CREATE POLICY ncm_auth_read ON public.noaa_customer_memory
  FOR SELECT TO authenticated USING (true);

