1	import { createContext, useContext, useEffect, useState, ReactNode } from 'react';
2	import { useAuth } from './useAuth';
3	import { supabase } from '@/integrations/supabase/client';
4	import { wideError } from '@/shared/lib/telemetry/wide-events';
5	import { handleError } from '@/shared/lib/error-handler';
6	
7	interface Permission {
8	  permission_name: string;
9	  permission_display_name: string;
10	  module: string;
11	}
12	
13	interface UserRole {
14	  role_name: string;
15	  role_display_name: string;
16	  can_change_store: boolean;
17	}
18	
19	interface PermissionsContextType {
20	  permissions: Permission[];
21	  userRole: UserRole | null;
22	  loading: boolean;
23	  hasPermission: (permissionName: string) => boolean;
24	  hasAnyPermission: (permissionNames: string[]) => boolean;
25	  isAdmin: () => boolean;
26	  canAccessModule: (module: string) => boolean;
27	  refreshPermissions: () => Promise<void>;
28	  canViewFinanceiro: () => boolean;
29	  canViewDashboard: () => boolean;
30	  canViewEstoque: () => boolean;
31	  canAdminPermissions: () => boolean;
32	  canViewLogistica: () => boolean;
33	  canViewRequisicao: () => boolean;
34	  canViewNotasFiscais: () => boolean;
35	  canViewEncomendas: () => boolean;
36	  canViewNCM: () => boolean;
37	  canViewEventos: () => boolean;
38	  canViewProntaEntrega: () => boolean;
39	  canViewMia: () => boolean;
40	  canSwitchStore: () => boolean;
41	  canSelectStoreNF: () => boolean;
42	}
43	
44	const PermissionsContext = createContext<PermissionsContextType | undefined>(undefined);
45	
46	export function PermissionsProvider({ children }: { children: ReactNode }) {
47	  const { user } = useAuth();
48	  const [permissions, setPermissions] = useState<Permission[]>([]);
49	  const [userRole, setUserRole] = useState<UserRole | null>(null);
50	  const [profileSelectStoreNF, setProfileSelectStoreNF] = useState<boolean>(false);
51	  const [loading, setLoading] = useState(true);
52	
53	  const fetchUserPermissions = async () => {
54	    if (!user) {
55	      setPermissions([]);
56	      setUserRole(null);
57	      setProfileSelectStoreNF(false);
58	      setLoading(false);
59	      return;
60	    }
61	
62	    try {
63	      setLoading(true);
64	
65	      // Buscar permissões do usuário
66	      const { data: permissionsData, error: permissionsError } = await supabase
67	        .rpc('get_user_permissions', { user_uuid: user.id });
68	
69	      if (permissionsError) {
70	        wideError('permissions.fetch_error', 'Erro ao buscar permissões do usuário', {
71	          attributes: {
72	            'permissions.error_code': permissionsError.code,
73	            'permissions.error_message': permissionsError.message,
74	            'permissions.user_id': user.id,
75	          },
76	        });
77	        setPermissions([]);
78	      } else {
79	        setPermissions(permissionsData || []);
80	      }
81	
82	      // Buscar role do usuário com can_change_store e flags de perfil
83	      const { data: profileData, error: profileError } = await supabase
84	        .from('profiles')
85	        .select('can_select_store_nf, user_roles(*)')
86	        .eq('user_id', user.id)
87	        .single();
88	
89	      if (profileError) {
90	        wideError('permissions.role_fetch_error', 'Erro ao buscar role do usuário', {
91	          attributes: {
92	            'permissions.error_code': profileError.code,
93	            'permissions.error_message': profileError.message,
94	            'permissions.user_id': user.id,
95	          },
96	        });
97	        setUserRole(null);
98	        setProfileSelectStoreNF(false);
99	      } else {
100	        const role = profileData?.user_roles as { name: string; display_name: string; can_change_store: boolean } | null;
101	        setUserRole(role ? {
102	          role_name: role.name,
103	          role_display_name: role.display_name,
104	          can_change_store: role.can_change_store ?? false,
105	        } : null);
106	        setProfileSelectStoreNF(profileData?.can_select_store_nf ?? false);
107	      }
108	    } catch (error) {
109	      handleError(error, { domain: 'permissions', operation: 'fetchUserPermissions', showToast: false });
110	      setPermissions([]);
111	      setUserRole(null);
112	    } finally {
113	      setLoading(false);
114	    }
115	  };
116	
117	  useEffect(() => {
118	    // Só buscar permissões se o usuário mudou realmente (não apenas re-renderizou)
119	    if (user && (!userRole || permissions.length === 0)) {
120	      fetchUserPermissions();
121	    } else if (!user) {
122	      // Limpar permissões se não há usuário
123	      setPermissions([]);
124	      setUserRole(null);
125	      setLoading(false);
126	    }
127	  }, [user?.id]); // Usar user.id ao invés de user para evitar re-renders desnecessários
128	
129	  const hasPermission = (permissionName: string): boolean => {
130	    return permissions.some(p => p.permission_name === permissionName);
131	  };
132	
133	  const hasAnyPermission = (permissionNames: string[]): boolean => {
134	    return permissionNames.some(permissionName => hasPermission(permissionName));
135	  };
136	
137	  const isAdmin = (): boolean => {
138	    // Tornar detecção de admin resiliente a variações de nome/idioma
139	    const roleName = userRole?.role_name?.toLowerCase();
140	    const adminAliases = ['admin', 'administrador', 'administrator'];
141	    const result = roleName ? adminAliases.includes(roleName) : false;
142	
143	    return result;
144	  };
145	
146	  const canAccessModule = (module: string): boolean => {
147	    if (isAdmin()) return true;
148	    return permissions.some(p => p.module === module);
149	  };
150	
151	  // Funções específicas para controle de acesso às páginas
152	  const canViewFinanceiro = (): boolean => {
153	    return hasPermission('view_financeiro') || isAdmin();
154	  };
155	
156	
157	
158	  const canViewDashboard = (): boolean => {
159	    return hasPermission('view_dashboard') || isAdmin();
160	  };
161	
162	  const canViewEstoque = (): boolean => {
163	    return canAccessModule('estoque');
164	  };
165	
166	  const canAdminPermissions = (): boolean => {
167	    return hasPermission('admin_permissions') || isAdmin();
